insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e782a64b-7797-4519-a216-0e7cf3876aae', 'N4', 'Vていただけませんか', 'Anh/chị ~ giúp tôi được không ạ?', 'いただけませんか = xin phép nhờ ai đó làm gì một cách lịch sự, khiêm nhường', 'V-て + いただけませんか', 'Nhờ vả ai đó làm gì một cách lịch sự, khiêm nhường', 'lịch sự, khiêm nhường ngữ', NULL, NULL, '{}', NULL, 38, 'Vていただけませんか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a67d61dd-d9a9-4672-9e3e-1b068628ce30', 'N4', '疑問詞 + Vたらいいですか', 'Nên làm như thế nào bây giờ', 'たら + いいですか = hỏi xin ý kiến/lời khuyên', '疑問詞(どう/何/どうやって...) + V(thể た) + らいいですか', 'Hỏi xin lời khuyên/ý kiến nên làm gì', NULL, NULL, NULL, '{}', NULL, 38, '疑問詞 + Vたらいいですか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', 'N4', 'Vる/Vた/Vない/Aい/A/Nな + んです', 'Giải thích lý do, mào đầu, làm mềm câu', 'んです thêm sắc thái giải thích/xin thông cảm vào câu nói', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 38, 'Vる/Vた/Vない/Aい/A/Nな + んです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('60671dc5-7e07-4c22-a037-8627c03f4041', 'N4', 'N + が + V(thể khả năng)', 'Thể khả năng (có thể làm gì)', 'Trợ từ を của động từ gốc chuyển thành が khi chia thể khả năng', 'N + が + V(thể khả năng)', 'Diễn tả khả năng làm được việc gì', NULL, NULL, NULL, '{}', NULL, 38, 'N + が + V(thể khả năng)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('af1ae8f4-759e-4b1e-8882-078bce1a6704', 'N4', 'N1は(+)が、N2は(−)', 'N1 thì ~, nhưng N2 thì ~', 'Đối lập 2 mệnh đề bằng が (nhưng)', 'N1は...ますが、N2はあまり...ません', 'So sánh đối lập khả năng/tình trạng giữa 2 đối tượng', NULL, NULL, NULL, '{}', NULL, 38, 'N1は(+)が、N2は(−)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cc6ef598-1afe-463d-931d-d156b4853140', 'N4', 'Nができます。/ Vることができます。', 'Có thể làm / Hoàn thành', 'できる = có thể / xong việc, tùy ngữ cảnh', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 38, 'Nができます。/ Vることができます。', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a89d36cb-09f1-4928-8523-5e1a8c998a04', 'N4', 'V1ながら、V2', 'Vừa làm việc này, vừa làm việc kia', 'V1(dạng ます, bỏ ます) + ながら', 'V1(bỏ ます) + ながら、V2', 'Diễn tả 2 hành động xảy ra đồng thời', NULL, NULL, NULL, '{}', NULL, 38, 'V1ながら、V2', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('335d2a21-37a3-465e-82e8-859150378ad1', 'N4', 'V1ながら、Vる人が + すき・きらい', 'Thích/Ghét ai đó vừa làm việc này, vừa làm việc kia', 'Áp dụng ながら vào việc nhận xét thói quen của người khác', 'V1ながら + V2る + 人が + 好き／嫌い', 'Bày tỏ cảm xúc thích/ghét về người có thói quen làm 2 việc cùng lúc', NULL, NULL, NULL, '{}', NULL, 38, 'V1ながら、Vる人が + すき・きらい', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ba4501f1-49b2-43e1-a212-342d92c7b396', 'N4', 'Sは~し、~し、(それに)~', 'Liệt kê các tính chất tương đồng nhau', 'し liệt kê nhiều lý do/tính chất cùng chiều, それに = hơn nữa', 'Sは...し、...し、(それに)...', 'Liệt kê nhiều đặc điểm tốt (hoặc xấu) cùng chiều về 1 chủ thể', NULL, NULL, NULL, '{}', NULL, 38, 'Sは~し、~し、(それに)~', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('6b9cb65b-d7ba-4517-9e9f-d6333da777d8', 'N4', 'Sは~し、~し、(それで)~', 'Liệt kê lý do', 'し liệt kê nhiều lý do, それで = vì thế (kết quả)', 'Sは...し、...し、(それで)...', 'Liệt kê nhiều lý do dẫn đến 1 kết quả/hành động', NULL, NULL, NULL, '{}', NULL, 38, 'Sは~し、~し、(それで)~', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ee3a4296-4cf9-4b33-a9f2-a76e7828de18', 'N4', 'いつもVています', 'Diễn tả thói quen', 'いつも + V-て + います = luôn luôn làm gì (thói quen)', 'いつも + V-て + います', 'Diễn tả thói quen lặp đi lặp lại', NULL, NULL, NULL, '{}', NULL, 38, 'いつもVています', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('eae25fb4-1d8d-4910-a34f-d4bb93063ff2', 'N4', 'Vてしまう', 'Hoàn thành / Lỡ làm gì đó (tiếc nuối)', 'てしまう mang 2 sắc thái: hoàn thành trọn vẹn, hoặc lỡ làm (tiếc nuối)', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 38, 'Vてしまう', 'pdf', 'ok')
