insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e782a64b-7797-4519-a216-0e7cf3876aae', NULL, 1, 'daily', 'いい先生を紹介していただけませんか。', 'Bạn có thể giới thiệu giúp tôi một giáo viên giỏi không?', 'いい先生を＿＿＿。', '紹介していただけませんか', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e782a64b-7797-4519-a216-0e7cf3876aae', NULL, 2, 'daily', 'この漢字の読み方を教えていただけませんか。', 'Bạn có thể dạy tôi cách đọc kanji này không ạ?', 'この漢字の読み方を＿＿＿。', '教えていただけませんか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e782a64b-7797-4519-a216-0e7cf3876aae', NULL, 3, 'daily', '明日、少し早く来ていただけませんか。', 'Ngày mai anh/chị có thể đến sớm một chút được không ạ?', '明日、少し早く＿＿＿。', '来ていただけませんか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a67d61dd-d9a9-4672-9e3e-1b068628ce30', NULL, 1, 'daily', 'バレンタインデーに女性に何をあげたらいいですか。', 'Nên tặng gì cho bạn gái vào ngày Valentine nhỉ?', 'バレンタインデーに女性に＿＿＿。', '何をあげたらいいですか', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a67d61dd-d9a9-4672-9e3e-1b068628ce30', NULL, 2, 'daily', 'この漢字はどう読んだらいいですか。', 'Kanji này nên đọc như thế nào nhỉ?', 'この漢字は＿＿＿。', 'どう読んだらいいですか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a67d61dd-d9a9-4672-9e3e-1b068628ce30', NULL, 3, 'daily', '駅までどうやって行ったらいいですか。', 'Nên đi đến ga bằng cách nào nhỉ?', '駅まで＿＿＿。', 'どうやって行ったらいいですか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', '3aa11b61-0d9a-4e94-b2fe-53f54e893a96', 1, 'daily', 'まだよくわからないんですが、もう一度教えていただけませんか。', 'Tôi chưa hiểu rõ, bạn có thể chỉ lại cho tôi 1 lần nữa được không?', 'まだよくわからない＿＿＿が、もう一度教えていただけませんか。', 'んです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', '3aa11b61-0d9a-4e94-b2fe-53f54e893a96', 2, 'daily', '明日、旅行に行くんですが、天気は大丈夫でしょうか。', 'Ngày mai tôi đi du lịch, không biết thời tiết có ổn không nhỉ.', '明日、旅行に行く＿＿＿が、天気は大丈夫でしょうか。', 'んです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', '3aa11b61-0d9a-4e94-b2fe-53f54e893a96', 3, 'daily', '今、忙しいんですが、後で連絡してもいいですか。', 'Bây giờ tôi đang bận, lát nữa liên lạc lại có được không?', '今、忙しい＿＿＿が、後で連絡してもいいですか。', 'んです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', 'efeea555-90b8-4543-b4de-b0661faf07ce', 1, 'daily', 'どうして遅れたんですか。バスが来なかったんです。', 'Tại sao bạn lại đến muộn? Bởi vì xe buýt đã không tới.', 'どうして遅れた＿＿＿か。', 'んです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', 'efeea555-90b8-4543-b4de-b0661faf07ce', 2, 'daily', 'どうして食べないんですか。お腹がいっぱいなんです。', 'Tại sao bạn không ăn? Vì tôi no rồi.', 'どうして食べない＿＿＿か。', 'んです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', 'efeea555-90b8-4543-b4de-b0661faf07ce', 3, 'daily', 'どうして休んだんですか。風邪をひいたんです。', 'Tại sao bạn nghỉ? Vì tôi bị cảm.', 'どうして休んだ＿＿＿か。', 'んです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', 'e6636fdc-ecb7-4c28-927f-d06f5aef196b', 1, 'daily', 'どうしたんですか。調子が悪いんです。', 'Bạn sao thế? Tôi không được khỏe.', 'どうした＿＿＿か。', 'んです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', 'e6636fdc-ecb7-4c28-927f-d06f5aef196b', 2, 'daily', '顔色が悪いですね。どうしたんですか。ちょっと疲れているんです。', 'Sắc mặt bạn không tốt nhỉ. Bạn sao thế? Tôi hơi mệt.', '顔色が悪いですね。どうした＿＿＿か。', 'んです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0e00dbf9-5f33-4c3b-83a1-9fe0c9155c27', 'e6636fdc-ecb7-4c28-927f-d06f5aef196b', 3, 'daily', '何を探しているんですか。鍵を探しているんです。', 'Bạn đang tìm gì vậy? Tôi đang tìm chìa khóa.', '何を探している＿＿＿か。', 'んです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('60671dc5-7e07-4c22-a037-8627c03f4041', NULL, 1, 'daily', '漢字が書ける。', 'Tôi có thể viết chữ Hán.', '漢字が＿＿＿。', '書ける', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('60671dc5-7e07-4c22-a037-8627c03f4041', NULL, 2, 'daily', '彼はピアノが弾ける。', 'Anh ấy có thể chơi piano.', '彼はピアノが＿＿＿。', '弾ける', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('60671dc5-7e07-4c22-a037-8627c03f4041', NULL, 3, 'daily', '私は辛い物が食べられる。', 'Tôi có thể ăn đồ cay.', '私は辛い物が＿＿＿。', '食べられる', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('af1ae8f4-759e-4b1e-8882-078bce1a6704', NULL, 1, 'daily', '日本語は話せますが、英語はあまり話せません。', 'Tôi có thể nói tiếng Nhật nhưng tiếng Anh thì không.', '日本語は話せますが、英語は＿＿＿。', 'あまり話せません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('af1ae8f4-759e-4b1e-8882-078bce1a6704', NULL, 2, 'daily', '漢字は読めますが、書くのは難しいです。', 'Tôi đọc được kanji nhưng viết thì khó.', '漢字は読めますが、書くのは＿＿＿。', '難しいです', 'generated');
