insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cc6ef598-1afe-463d-931d-d156b4853140', 'd228ae81-21d0-4f35-b915-3ee5634dfd56', 1, 'daily', 'レポートはいつできますか。明日できます。', 'Khi nào bạn có thể làm xong báo cáo? Ngày mai tôi có thể làm xong.', 'レポートはいつ＿＿＿か。', 'できます', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cc6ef598-1afe-463d-931d-d156b4853140', 'd228ae81-21d0-4f35-b915-3ee5634dfd56', 2, 'daily', '宿題はもうできましたか。はい、もうできました。', 'Bài tập đã xong chưa? Vâng, xong rồi.', '宿題はもう＿＿＿か。', 'できました', 'generated');
