insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a89d36cb-09f1-4928-8523-5e1a8c998a04', NULL, 1, 'daily', 'テレビを見ながら、ご飯を食べます。', 'Chúng tôi vừa ăn cơm vừa xem TV.', 'テレビを＿＿＿、ご飯を食べます。', '見ながら', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a89d36cb-09f1-4928-8523-5e1a8c998a04', NULL, 2, 'daily', '音楽を聞きながら、勉強します。', 'Vừa nghe nhạc vừa học bài.', '音楽を＿＿＿、勉強します。', '聞きながら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a89d36cb-09f1-4928-8523-5e1a8c998a04', NULL, 3, 'daily', '歩きながら、電話で話します。', 'Vừa đi bộ vừa nói chuyện điện thoại.', '＿＿＿、電話で話します。', '歩きながら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('335d2a21-37a3-465e-82e8-859150378ad1', NULL, 1, 'daily', '電話を使いながらご飯を食べる人がきらいです。', 'Tôi ghét người mà vừa ăn cơm vừa dùng điện thoại.', '電話を使いながらご飯を食べる人が＿＿＿。', 'きらいです', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('335d2a21-37a3-465e-82e8-859150378ad1', NULL, 2, 'daily', '音楽を聞きながら勉強する人が好きです。', 'Tôi thích người vừa nghe nhạc vừa học bài.', '音楽を聞きながら勉強する人が＿＿＿。', '好きです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('335d2a21-37a3-465e-82e8-859150378ad1', NULL, 3, 'daily', '歩きながらタバコを吸う人がきらいです。', 'Tôi ghét người vừa đi bộ vừa hút thuốc.', '歩きながらタバコを吸う人が＿＿＿。', 'きらいです', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ba4501f1-49b2-43e1-a212-342d92c7b396', NULL, 1, 'daily', '先生は面白いし、親切だし、それに経験もあります。', 'Giáo viên vui tính, tốt bụng, hơn nữa còn giàu kinh nghiệm.', '先生は面白いし、親切だし、＿＿＿経験もあります。', 'それに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ba4501f1-49b2-43e1-a212-342d92c7b396', NULL, 2, 'daily', 'この店は安いし、おいしいし、それに店員も親切です。', 'Quán này rẻ, ngon, hơn nữa nhân viên còn thân thiện.', 'この店は安いし、おいしいし、＿＿＿店員も親切です。', 'それに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ba4501f1-49b2-43e1-a212-342d92c7b396', NULL, 3, 'daily', '彼は頭がいいし、優しいし、それにハンサムです。', 'Anh ấy thông minh, hiền lành, hơn nữa còn đẹp trai.', '彼は頭がいいし、優しいし、＿＿＿ハンサムです。', 'それに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6b9cb65b-d7ba-4517-9e9f-d6333da777d8', NULL, 1, 'daily', '雨も降っているし、荷物も多いし、それでタクシーで帰りました。', 'Trời mưa và có rất nhiều hành lý, vì vậy tôi đã bắt taxi về nhà.', '雨も降っているし、荷物も多いし、＿＿＿タクシーで帰りました。', 'それで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6b9cb65b-d7ba-4517-9e9f-d6333da777d8', NULL, 2, 'daily', '頭も痛いし、熱もあるし、それで会社を休みました。', 'Đau đầu và có sốt, vì vậy tôi đã nghỉ làm.', '頭も痛いし、熱もあるし、＿＿＿会社を休みました。', 'それで', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('6b9cb65b-d7ba-4517-9e9f-d6333da777d8', NULL, 3, 'daily', '道も混んでいるし、時間もないし、それで電車で行きました。', 'Đường tắc và không có thời gian, vì vậy tôi đã đi bằng tàu điện.', '道も混んでいるし、時間もないし、＿＿＿電車で行きました。', 'それで', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ee3a4296-4cf9-4b33-a9f2-a76e7828de18', NULL, 1, 'daily', '暇なとき、いつもテレビを見ています。', 'Lúc rảnh rồi tôi thường xem TV.', '暇なとき、いつも＿＿＿。', 'テレビを見ています', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ee3a4296-4cf9-4b33-a9f2-a76e7828de18', NULL, 2, 'daily', '毎朝、いつも六時に起きています。', 'Mỗi sáng tôi luôn dậy lúc 6 giờ.', '毎朝、いつも＿＿＿。', '六時に起きています', 'generated');
